<script setup lang="ts">
// @ts-nocheck
import{onMounted,ref}from'vue';import{useRoute}from'vue-router';import{VueFlow,useVueFlow,type Node,type Edge}from'@vue-flow/core';import'@vue-flow/core/dist/style.css';import'@vue-flow/core/dist/theme-default.css';import{api}from'../api';const pid=Number(useRoute().params.id),flows=ref<any[]>([]),runs=ref<any[]>([]),releases=ref<any[]>([]),name=ref('部署流程'),enabled=ref(true),triggerType=ref('any'),triggerGlob=ref('v*'),editing=ref<number>(),selected=ref<any>(),configText=ref('{}'),nodes=ref<Node[]>([]),edges=ref<Edge[]>([]),modules=['archive','extract','sftp_upload','ssh_command','http_webhook','checksum_verify'];const{addEdges}=useVueFlow();async function load(){[flows.value,runs.value,releases.value]=await Promise.all([api(`/api/projects/${pid}/workflows`),api(`/api/projects/${pid}/runs`),api(`/api/projects/${pid}/releases`)])}function add(type:string){const id=`${type}_${Date.now()}`;nodes.value.push({id,label:type,position:{x:80+nodes.value.length*35,y:80+nodes.value.length*35},data:{module:type,config:{},timeout_seconds:600,retries:0}})}function onConnect(e:any){addEdges([e])}function choose(e:any){selected.value=e.node;configText.value=JSON.stringify(e.node.data.config||{},null,2)}function applyConfig(){if(selected.value)selected.value.data.config=JSON.parse(configText.value)}async function edit(id:number){const w=await api<any>(`/api/projects/${pid}/workflows/${id}`);editing.value=id;name.value=w.name;enabled.value=w.enabled;triggerType.value=w.trigger_type;triggerGlob.value=w.trigger_glob;nodes.value=w.definition.nodes.map((n:any)=>({id:n.id,label:n.type,position:n.position||{x:100,y:100},data:{module:n.type,config:n.config,timeout_seconds:n.timeout_seconds,retries:n.retries}}));edges.value=w.definition.edges.map((e:any,i:number)=>({id:`e${i}`,source:e.from,target:e.to}))}async function save(){const definition={nodes:nodes.value.map(n=>({id:n.id,type:n.data.module,config:n.data.config,timeout_seconds:n.data.timeout_seconds,retries:n.data.retries,position:n.position})),edges:edges.value.map(e=>({from:e.source,to:e.target}))};await api(editing.value?`/api/projects/${pid}/workflows/${editing.value}`:`/api/projects/${pid}/workflows`,{method:editing.value?'PUT':'POST',body:JSON.stringify({name:name.value,enabled:enabled.value,trigger_type:triggerType.value,trigger_glob:triggerGlob.value,definition})});await load()}async function run(flow:number,release:number){if(!release)return;await api(`/api/projects/${pid}/workflows/${flow}/runs`,{method:'POST',body:JSON.stringify({release_id:release})});await load()}onMounted(load)
</script>
<template><router-link :to="`/projects/${pid}`">← 项目</router-link><h1>部署工作流</h1><div class="workflow-layout"><aside class="card palette"><h2>模块</h2><button v-for="m in modules" :key="m" @click="add(m)">{{m}}</button><hr><label>名称<input v-model="name"></label><label>触发<select v-model="triggerType"><option value="any">任意版本</option><option value="tag">仅 Tag</option><option value="commit">仅 Commit</option><option value="tag_glob">Tag glob</option></select></label><label v-if="triggerType==='tag_glob'">Glob<input v-model="triggerGlob"></label><label><input v-model="enabled" type="checkbox"> 启用</label><button @click="save">保存工作流</button></aside><section class="card graph"><VueFlow v-model:nodes="nodes" v-model:edges="edges" fit-view-on-init @connect="onConnect" @node-click="choose" /></section><aside class="card inspector"><h2>节点配置</h2><template v-if="selected"><label>超时秒<input v-model.number="selected.data.timeout_seconds" type="number"></label><label>重试<input v-model.number="selected.data.retries" type="number"></label><textarea v-model="configText" rows="16"></textarea><button @click="applyConfig">应用 JSON</button></template></aside></div><section class="card"><h2>工作流</h2><table><tr v-for="f in flows" :key="f.id"><td>{{f.name}}</td><td>{{f.trigger_type}}</td><td><button class="link" @click="edit(f.id)">编辑</button></td><td><select @change="run(f.id,Number(($event.target as HTMLSelectElement).value))"><option value="">手动运行…</option><option v-for="r in releases" :value="r.id">{{r.version}}</option></select></td></tr></table></section><section class="card"><h2>运行历史</h2><table><tr v-for="r in runs" :key="r.id"><td>#{{r.id}}</td><td>{{r.status}}</td><td>{{new Date(r.created_at).toLocaleString()}}</td></tr></table></section></template>
